#include <iostream>
#include <iomanip>

class Loan {
private:
    double annualInterestRate{2.5};
    int numberOfYears{1};
    double loanAmount{1000.0};
public:
    Loan() = default;
    Loan(double rate, int years, double amount)
        : annualInterestRate(rate), numberOfYears(years), loanAmount(amount) {}

    double getLoanAmount() const {
        return loanAmount;
    }
};

class Container {
public:
    Loan loan;
    int primitiveVal{42}; // Modern C++ in-class default initialization
};

int main() {
    Container obj;
    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Loan amount: " << obj.loan.getLoanAmount() << "\n";
    std::cout << "Container val: " << obj.primitiveVal << "\n";
    return 0;
}

#include <iostream>

class Fan {
private:
    int speed{1};
    bool on{false};
    double radius{5.0};

public:
    Fan() = default;
    Fan(int s, bool state, double r) : speed(s), on(state), radius(r) {}

    int getSpeed() const { return speed; }
    void setSpeed(int s) { speed = s; }

    bool isOn() const { return on; }
    void setOn(bool state) { on = state; }

    double getRadius() const { return radius; }
    void setRadius(double r) { radius = r; }
};

int main() {
    Fan fan1(3, true, 10.0);
    Fan fan2(2, false, 5.0);

    std::cout << std::boolalpha;
    std::cout << "Fan 1: speed=" << fan1.getSpeed() 
              << ", on=" << fan1.isOn() 
              << ", radius=" << fan1.getRadius() << "\n";
    std::cout << "Fan 2: speed=" << fan2.getSpeed() 
              << ", on=" << fan2.isOn() 
              << ", radius=" << fan2.getRadius() << "\n";
    return 0;
}
